/** Write a `CT_R`; the caller supplies its element local name. */
export function writeCT_R(s: XmlSink, value: CT_R, ctx: WriteContext, localName: string): void {
  s.startElement(uriFor(ctx, 'math'), localName);
  if (value['rPr'] !== undefined) writeCT_RPR(s, value['rPr'], ctx, 'rPr');
  if (value['rPr2'] !== undefined) writeCT_RPr(s, value['rPr2'], ctx, 'rPr');
  for (const v_content of value['content']) {
    if (v_content.kind === 'br') writeCT_Br(s, v_content.value, ctx, 'br');
    if (v_content.kind === 't_wml') wml_writeCT_Text(s, v_content.value, ctx, 't');
    if (v_content.kind === 'contentPart') writeCT_Rel(s, v_content.value, ctx, 'contentPart');
    if (v_content.kind === 'delText') wml_writeCT_Text(s, v_content.value, ctx, 'delText');
    if (v_content.kind === 'instrText') wml_writeCT_Text(s, v_content.value, ctx, 'instrText');
    if (v_content.kind === 'delInstrText') wml_writeCT_Text(s, v_content.value, ctx, 'delInstrText');
    if (v_content.kind === 'noBreakHyphen') writeCT_Empty(s, v_content.value, ctx, 'noBreakHyphen');
    if (v_content.kind === 'softHyphen') writeCT_Empty(s, v_content.value, ctx, 'softHyphen');
    if (v_content.kind === 'dayShort') writeCT_Empty(s, v_content.value, ctx, 'dayShort');
    if (v_content.kind === 'monthShort') writeCT_Empty(s, v_content.value, ctx, 'monthShort');
    if (v_content.kind === 'yearShort') writeCT_Empty(s, v_content.value, ctx, 'yearShort');
    if (v_content.kind === 'dayLong') writeCT_Empty(s, v_content.value, ctx, 'dayLong');
    if (v_content.kind === 'monthLong') writeCT_Empty(s, v_content.value, ctx, 'monthLong');
    if (v_content.kind === 'yearLong') writeCT_Empty(s, v_content.value, ctx, 'yearLong');
    if (v_content.kind === 'annotationRef') writeCT_Empty(s, v_content.value, ctx, 'annotationRef');
    if (v_content.kind === 'footnoteRef') writeCT_Empty(s, v_content.value, ctx, 'footnoteRef');
    if (v_content.kind === 'endnoteRef') writeCT_Empty(s, v_content.value, ctx, 'endnoteRef');
    if (v_content.kind === 'separator') writeCT_Empty(s, v_content.value, ctx, 'separator');
    if (v_content.kind === 'continuationSeparator') writeCT_Empty(s, v_content.value, ctx, 'continuationSeparator');
    if (v_content.kind === 'sym') writeCT_Sym(s, v_content.value, ctx, 'sym');
    if (v_content.kind === 'pgNum') writeCT_Empty(s, v_content.value, ctx, 'pgNum');
    if (v_content.kind === 'cr') writeCT_Empty(s, v_content.value, ctx, 'cr');
    if (v_content.kind === 'tab') writeCT_Empty(s, v_content.value, ctx, 'tab');
    if (v_content.kind === 'object') writeCT_Object(s, v_content.value, ctx, 'object');
    if (v_content.kind === 'pict') writeCT_Picture(s, v_content.value, ctx, 'pict');
    if (v_content.kind === 'fldChar') writeCT_FldChar(s, v_content.value, ctx, 'fldChar');
    if (v_content.kind === 'ruby') writeCT_Ruby(s, v_content.value, ctx, 'ruby');
    if (v_content.kind === 'footnoteReference') writeCT_FtnEdnRef(s, v_content.value, ctx, 'footnoteReference');
    if (v_content.kind === 'endnoteReference') writeCT_FtnEdnRef(s, v_content.value, ctx, 'endnoteReference');
    if (v_content.kind === 'commentReference') writeCT_Markup(s, v_content.value, ctx, 'commentReference');
    if (v_content.kind === 'drawing') writeCT_Drawing(s, v_content.value, ctx, 'drawing');
    if (v_content.kind === 'ptab') writeCT_PTab(s, v_content.value, ctx, 'ptab');
    if (v_content.kind === 'lastRenderedPageBreak') writeCT_Empty(s, v_content.value, ctx, 'lastRenderedPageBreak');
    if (v_content.kind === 't_math') writeCT_Text(s, v_content.value, ctx, 't');
    if (v_content.kind === '$raw') { s.raw(v_content.value); }
  }
  for (const a of value.$unknownAttrs ?? []) s.attr(a.uri || null, a.localName, a.value);
  s.endElement();
}

